(()=>{const bar=document.createElement('div');bar.id='offbar';bar.setAttribute('role','status');bar.textContent='You are offline. Changes will not save until you reconnect.';document.body.appendChild(bar);const upd=()=>bar.classList.toggle('on',!navigator.onLine);addEventListener('online',()=>{upd();toast('Back online')});addEventListener('offline',upd);upd();
addEventListener('unhandledrejection',e=>{const c=e.reason&&e.reason.code||'';if(!navigator.onLine||/unavailable|network|deadline/.test(c)){toast('No internet right now. Try again when you are connected.')}})})();

async function sharedView(){const sn=await getDocs(col('shared'));const ns=sn.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>b.updated.localeCompare(a.updated));
page('shared',`${head('Notes shared by students','Students choose which notes to share with you. You can only read them.')}${ns.length?`<div class="list">${ns.map(n=>`<div class="item"><div class="t"><b>${esc(n.title)}</b><span>${esc(n.name)} - ${esc(new Date(n.updated).toLocaleDateString('en-IN',{day:'numeric',month:'short'}))}</span></div><button class="small" data-o="${n.id}">Read</button></div>`).join('')}</div>`:empty('book','Nothing shared yet','When a student ticks Share with my teacher on a note, it shows up here.')}`);
document.querySelectorAll('[data-o]').forEach(b=>b.onclick=()=>{const n=ns.find(x=>x.id===b.dataset.o);modal(`<h2>${esc(n.title)}</h2><p class="hint">By ${esc(n.name)}</p><div style="white-space:pre-wrap;line-height:1.6;max-height:55vh;overflow:auto">${esc(n.body)}</div><div class="row" style="margin-top:12px"><button class="primary" id="cc">Close</button></div>`);$('cc').onclick=closeModal})}
